using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Identity.Models;
using Microsoft.AspNetCore.Identity;
using System.Security.Claims;

namespace Identity.Controllers
{
    [Authorize]
    public class ClaimsController : Controller
    {
        private readonly UserManager<AppUser> userManager;

        public ClaimsController(UserManager<AppUser> userMgr)
        {
            userManager = userMgr;
        }

        [Authorize(Policy = "AspManager")]
        public IActionResult Project()
            => View("Index", User?.Claims);
    }
}

using Microsoft.AspNetCore.Authorization;

namespace Identity.CustomPolicy
{
    public class AllowUserPolicy : IAuthorizationRequirement
    {
        public string[] AllowUsers { get; }

        public AllowUserPolicy(params string[] users)
        {
            AllowUsers = users;
        }
    }
}

using Microsoft.AspNetCore.Authorization;
using System.Threading.Tasks;

namespace Identity.CustomPolicy
{
    public class AllowUsersHandler
        : AuthorizationHandler<AllowUserPolicy>
    {
        protected override Task HandleRequirementAsync(
            AuthorizationHandlerContext context,
            AllowUserPolicy requirement)
        {
            bool isAllowed = requirement.AllowUsers.Any(user =>
                user.Equals(
                    context.User.Identity!.Name,
                    System.StringComparison.OrdinalIgnoreCase));

            if (isAllowed)
                context.Succeed(requirement);
            else
                context.Fail();

            return Task.CompletedTask;
        }
    }
}

builder.Services.AddTransient<
    IAuthorizationHandler, AllowUsersHandler>();

builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("AllowTom", policy =>
    {
        policy.AddRequirements(
            new AllowUserPolicy("tom"));
    });
});

